window.MG_LAZY_DATA["data/lazy/resources/hpc-v27-077-f4e48ef2303c12ad.json"]={sha256:"f4e48ef2303c12ad60ac97ddf4a9698fd701ce54e13867d8abd2d03bdfd85825",value:{"sources":[{"id":"v27-case-7d747ece7f87963b","url":"https://www.mumps-solver.org/index.php?page=doc","title":"MUMPS documentation","titleEn":"MUMPS documentation","publisher":"MUMPS consortium","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"hpc-v27-077","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"hpc-v27-077","related":[{"id":"hpc-v27-078","referenceUrls":["https://github.com/DrTimothyAldenDavis/SuiteSparse"],"title":"SuiteSparseQR：最小平方殘差與秩虧解辨識","titleEn":"SuiteSparseQR: least-squares residuals and rank-deficient solutions","why":"用兩課的可觀察驗收條件比較模型邊界：決策使用完整成本與品質證據，填充比只是一項指標。","whyEn":"Compare model boundaries using observable acceptance criteria: Use complete cost and quality evidence; fill ratio is only one decision metric.","difference":"使用原創合成資料研究「SuiteSparseQR：最小平方殘差與秩虧解辨識」，從物理或資料契約推導計算，並以反例驗證。完成：交付矩陣與殘差、正交性證明、變更觀測結果及相依欄反例。","differenceEn":"Investigate SuiteSparseQR: least-squares residuals and rank-deficient solutions using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver matrix and residual calculations, orthogonality evidence, changed-observation results and a dependent-column counterexample separating fitted predictions from coefficient uniqueness.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["將二十五萬除五萬，並畫原稀疏圖與新增填充示意；說明填充來源是消去產生的新耦合。","代入候選解算三列殘差，求二範數；再算兩個欄與殘差的內積，檢查正交。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Divide two hundred fifty thousand by fifty thousand and sketch original sparsity plus illustrative fill edges. Explain how elimination creates new couplings rather than assuming every factor entry existed in the original matrix.","Substitute the proposed solution, compute all three residuals and their Euclidean norm, then take each column dot product with the residual. This independently checks optimality rather than relying on a reported least-squares status.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"hpc-v27-087","referenceUrls":["https://balsam.readthedocs.io/en/stable/index.html"],"title":"Balsam：多任務裝箱、長尾與集合工期","titleEn":"Balsam: ensemble packing, long tails and makespan","why":"用兩課的可觀察驗收條件比較模型邊界：決策使用完整成本與品質證據，填充比只是一項指標。","whyEn":"Compare model boundaries using observable acceptance criteria: Use complete cost and quality evidence; fill ratio is only one decision metric.","difference":"使用原創合成資料研究「Balsam：多任務裝箱、長尾與集合工期」，從物理或資料契約推導計算，並以反例驗證。完成：交付兩種四槽時間圖、總工作下界、任務身分與尾端診斷。","differenceEn":"Investigate Balsam: ensemble packing, long tails and makespan using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver two four-slot timelines, a total-work lower bound, task identities and a tail diagnosis distinguishing scheduling effects from inaccurate workload estimates.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["將二十五萬除五萬，並畫原稀疏圖與新增填充示意；說明填充來源是消去產生的新耦合。","前四任務從零到四秒；兩長任務再從四到十二秒，標出後段空閒兩槽。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Divide two hundred fifty thousand by fifty thousand and sketch original sparsity plus illustrative fill edges. Explain how elimination creates new couplings rather than assuming every factor entry existed in the original matrix.","Run the four short tasks from zero to four seconds, then the two long tasks from four to twelve. Mark the two idle slots during the tail and explain why available capacity cannot accelerate nonpreemptive single-slot tasks automatically.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v27-case-16450ca99b8a2ba6","url":"https://github.com/DrTimothyAldenDavis/SuiteSparse","title":"SuiteSparse official library","titleEn":"SuiteSparse official library","publisher":"Timothy A. Davis / SuiteSparse","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v27-case-73005c1e24fd3480","url":"https://balsam.readthedocs.io/en/stable/index.html","title":"Balsam scientific workflow service","titleEn":"Balsam scientific workflow service","publisher":"Balsam project","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
